import org.jsoup.Connection;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import java.net.URL;
import java.io.UnsupportedEncodingException;
import static org.junit.Assert.assertNotNull;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class UrlBuilderTest {
    @Mock
    private URL mockUrl;

    @Mock
    private Connection.KeyVal mockKeyVal;

    @Test
    public void UrlBuilderConstructorValidUrlTest() {
        UrlBuilder urlBuilder = new UrlBuilder(mockUrl);
        assertNotNull(urlBuilder);
    }

    @Test(expected = IllegalArgumentException.class)
    public void UrlBuilderConstructorNullUrlTest() {
        UrlBuilder urlBuilder = new UrlBuilder(null);
    }

    @Test
    public void buildWithValidUrlTest() {
        UrlBuilder urlBuilder = new UrlBuilder(mockUrl);
        URL url = urlBuilder.build();
        assertNotNull(url);
    }

    @Test
    public void appendKeyValWithValidKeyValTest() throws UnsupportedEncodingException {
        when(mockKeyVal.key()).thenReturn("key");
        when(mockKeyVal.value()).thenReturn("value");

        UrlBuilder urlBuilder = new UrlBuilder(mockUrl);
        urlBuilder.appendKeyVal(mockKeyVal);
    }

    @Test(expected = UnsupportedEncodingException.class)
    public void appendKeyValWithInvalidKeyValTest() throws UnsupportedEncodingException {
        when(mockKeyVal.key()).thenReturn("invalid_key");
        when(mockKeyVal.value()).thenReturn("invalid_value");

        UrlBuilder urlBuilder = new UrlBuilder(mockUrl);
        urlBuilder.appendKeyVal(mockKeyVal);
    }
}
